=== FILE: sync_fifo.v ===
// sync_fifo.v
// Parameterizable synchronous FIFO.
// Traces to: requirement req-d57ae7630b; interface_spec.md; microarchitecture.md.
//
// - Occupancy kept in an explicit count register ($clog2(DEPTH+1) bits).
// - Pointers are $clog2(DEPTH) bits and wrap at LAST = DEPTH-1 by compare,
//   so a DEPTH that is not a power of two works.
// - wr_acc = wr_en && !full, rd_acc = rd_en && !empty: a write while full and
//   a read while empty are dropped with no side effect.
// - rd_data = mem[rd_ptr]: first-word fall-through, undefined while empty.
// - rst_n is synchronous, active low; storage is datapath and is not reset.
`default_nettype none

module sync_fifo #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       wr_en,
    input  wire [WIDTH-1:0]           wr_data,
    output wire                       full,
    input  wire                       rd_en,
    output wire [WIDTH-1:0]           rd_data,
    output wire                       empty,
    output wire [$clog2(DEPTH+1)-1:0] count
);

    localparam integer AW = $clog2(DEPTH);
    localparam integer CW = $clog2(DEPTH + 1);

    localparam [31:0]   DEPTH32  = DEPTH;
    localparam [31:0]   LAST32   = DEPTH - 1;
    localparam [31:0]   ONE32    = 32'd1;
    localparam [AW-1:0] LAST     = LAST32[AW-1:0];
    localparam [AW-1:0] PTR_ONE  = ONE32[AW-1:0];
    localparam [CW-1:0] CNT_ONE  = ONE32[CW-1:0];
    localparam [CW-1:0] CNT_FULL = DEPTH32[CW-1:0];

    // Storage (datapath, not reset)
    reg [WIDTH-1:0] mem [0:DEPTH-1];

    // Control state and next-state values
    reg [AW-1:0] wr_ptr;
    reg [AW-1:0] rd_ptr;
    reg [CW-1:0] count_q;
    reg [AW-1:0] wr_ptr_d;
    reg [AW-1:0] rd_ptr_d;
    reg [CW-1:0] count_d;

    wire wr_acc;
    wire rd_acc;

    // Flags are compares on a register: no input-to-flag combinational path
    assign full    = (count_q == CNT_FULL);
    assign empty   = (count_q == {CW{1'b0}});
    assign count   = count_q;

    // The flags gate the requests (overflow / underflow policy)
    assign wr_acc  = wr_en & ~full;
    assign rd_acc  = rd_en & ~empty;

    // First-word fall-through read of the oldest slot
    assign rd_data = mem[rd_ptr];

    // Next-state logic
    always @* begin
        wr_ptr_d = wr_ptr;
        rd_ptr_d = rd_ptr;
        count_d  = count_q;

        if (wr_acc) begin
            if (wr_ptr == LAST) begin
                wr_ptr_d = {AW{1'b0}};
            end else begin
                wr_ptr_d = wr_ptr + PTR_ONE;
            end
        end

        if (rd_acc) begin
            if (rd_ptr == LAST) begin
                rd_ptr_d = {AW{1'b0}};
            end else begin
                rd_ptr_d = rd_ptr + PTR_ONE;
            end
        end

        if (wr_acc && !rd_acc) begin
            count_d = count_q + CNT_ONE;
        end else if (rd_acc && !wr_acc) begin
            count_d = count_q - CNT_ONE;
        end
    end

    // Control registers: synchronous active-low reset
    always @(posedge clk) begin
        if (!rst_n) begin
            wr_ptr  <= {AW{1'b0}};
            rd_ptr  <= {AW{1'b0}};
            count_q <= {CW{1'b0}};
        end else begin
            wr_ptr  <= wr_ptr_d;
            rd_ptr  <= rd_ptr_d;
            count_q <= count_d;
        end
    end

    // Storage write, only outside reset
    always @(posedge clk) begin
        if (rst_n && wr_acc) begin
            mem[wr_ptr] <= wr_data;
        end
    end

`ifdef FORMAL
    // ------------------------------------------------------------------
    // Design-intent properties (microarchitecture.md section 6)
    // ------------------------------------------------------------------
    reg f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    // Reset is active on the first cycle
    always @(*) begin
        if (!f_past_valid) assume(!rst_n);
    end

    // One solver-chosen slot
    (* anyconst *) reg [AW-1:0] f_addr;
    always @(*) assume(f_addr <= LAST);

    wire [31:0] f_wr32   = {{(32-AW){1'b0}}, wr_ptr};
    wire [31:0] f_rd32   = {{(32-AW){1'b0}}, rd_ptr};
    wire [31:0] f_addr32 = {{(32-AW){1'b0}}, f_addr};
    wire [31:0] f_cnt32  = {{(32-CW){1'b0}}, count_q};
    wire [31:0] f_sum    = f_rd32 + f_cnt32;
    wire [31:0] f_wr_exp = (f_sum >= DEPTH32) ? (f_sum - DEPTH32) : f_sum;
    wire [31:0] f_off    = (f_addr32 >= f_rd32) ? (f_addr32 - f_rd32)
                                                : (f_addr32 + DEPTH32 - f_rd32);
    wire        f_occupied = (f_off < f_cnt32);
    wire [WIDTH-1:0] f_mem_word = mem[f_addr];

    // Shadow of the word last written to the chosen slot
    reg [WIDTH-1:0] f_word;
    always @(posedge clk) begin
        if (rst_n && wr_acc && (wr_ptr == f_addr)) f_word <= wr_data;
    end

    // Invariants
    always @(*) begin
        if (f_past_valid) begin
            assert(f_cnt32 <= DEPTH32);
            assert(wr_ptr <= LAST);
            assert(rd_ptr <= LAST);
            assert(full == (count_q == CNT_FULL));
            assert(empty == (count_q == {CW{1'b0}}));
            assert(!(full && empty));
            assert(f_wr32 == f_wr_exp);
            if (f_occupied) begin
                assert(f_mem_word == f_word);
                assert(!(wr_acc && (wr_ptr == f_addr)));
            end
            if (f_occupied && (rd_ptr == f_addr)) begin
                assert(rd_data == f_word);
            end
        end
    end

    // Step properties
    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                assert(count_q == {CW{1'b0}});
                assert(wr_ptr == {AW{1'b0}});
                assert(rd_ptr == {AW{1'b0}});
                assert(empty);
                assert(!full);
            end else begin
                // count moves by exactly the accepted requests
                if ($past(wr_acc) && !$past(rd_acc)) begin
                    assert(count_q == $past(count_q) + CNT_ONE);
                end else if (!$past(wr_acc) && $past(rd_acc)) begin
                    assert(count_q == $past(count_q) - CNT_ONE);
                end else begin
                    assert(count_q == $past(count_q));
                end

                // write pointer
                if ($past(wr_acc)) begin
                    if ($past(wr_ptr) == LAST) assert(wr_ptr == {AW{1'b0}});
                    else assert(wr_ptr == $past(wr_ptr) + PTR_ONE);
                end else begin
                    assert(wr_ptr == $past(wr_ptr));
                end

                // read pointer
                if ($past(rd_acc)) begin
                    if ($past(rd_ptr) == LAST) assert(rd_ptr == {AW{1'b0}});
                    else assert(rd_ptr == $past(rd_ptr) + PTR_ONE);
                end else begin
                    assert(rd_ptr == $past(rd_ptr));
                end

                // a write while full changes nothing on the write side
                if ($past(full) && $past(wr_en)) begin
                    assert(wr_ptr == $past(wr_ptr));
                    assert(f_mem_word == $past(f_mem_word));
                end

                // a read while empty changes nothing on the read side
                if ($past(empty) && $past(rd_en)) begin
                    assert(rd_ptr == $past(rd_ptr));
                end
            end
        end
    end

    // Covers
    reg f_was_full = 1'b0;
    always @(posedge clk) begin
        if (!rst_n) f_was_full <= 1'b0;
        else if (full) f_was_full <= 1'b1;
    end

    always @(*) begin
        if (f_past_valid && rst_n) begin
            cover(full);
            cover(full && wr_en);
            cover(empty && rd_en);
            cover(wr_acc && rd_acc);
            cover(f_was_full && empty);
            cover(f_occupied && (rd_ptr == f_addr) && rd_acc);
        end
    end
`endif

endmodule

`default_nettype wire
=== END FILE ===
