// sync_fifo_tb.v
// Self-checking testbench for sync_fifo (interface_spec.md section 7).
// Two FIFOs on one stimulus: DEPTH 8 x WIDTH 8 and DEPTH 5 x WIDTH 12.
// Each has a reference-queue scoreboard (sync_fifo_tb_sb) that checks
// full, empty, count and rd_data every cycle.
`default_nettype none

module sync_fifo_tb;

    localparam integer DA  = 8;
    localparam integer WA  = 8;
    localparam integer DB  = 5;
    localparam integer WB  = 12;
    localparam integer CWA = $clog2(DA + 1);
    localparam integer CWB = $clog2(DB + 1);

    reg          clk;
    reg          rst_n;
    reg          wr_en;
    reg          rd_en;
    reg [WB-1:0] wr_data;

    wire           full_a;
    wire           empty_a;
    wire [WA-1:0]  rd_data_a;
    wire [CWA-1:0] count_a;

    wire           full_b;
    wire           empty_b;
    wire [WB-1:0]  rd_data_b;
    wire [CWB-1:0] count_b;

    wire [31:0] pass_a;
    wire [31:0] fail_a;
    wire [31:0] pass_b;
    wire [31:0] fail_b;
    wire [9:0]  miss_a;
    wire [9:0]  miss_b;

    reg [31:0]      passed;
    reg [31:0]      failed;
    reg [8*64-1:0]  nonce;

    initial clk = 1'b0;
    always #5 clk = ~clk;

    sync_fifo #(.DEPTH(DA), .WIDTH(WA)) dut_a (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (wr_en),
        .wr_data (wr_data[WA-1:0]),
        .full    (full_a),
        .rd_en   (rd_en),
        .rd_data (rd_data_a),
        .empty   (empty_a),
        .count   (count_a)
    );

    sync_fifo #(.DEPTH(DB), .WIDTH(WB)) dut_b (
        .clk     (clk),
        .rst_n   (rst_n),
        .wr_en   (wr_en),
        .wr_data (wr_data),
        .full    (full_b),
        .rd_en   (rd_en),
        .rd_data (rd_data_b),
        .empty   (empty_b),
        .count   (count_b)
    );

    sync_fifo_tb_sb #(.DEPTH(DA), .WIDTH(WA)) sb_a (
        .clk      (clk),
        .rst_n    (rst_n),
        .wr_en    (wr_en),
        .wr_data  (wr_data[WA-1:0]),
        .rd_en    (rd_en),
        .full     (full_a),
        .empty    (empty_a),
        .count    (count_a),
        .rd_data  (rd_data_a),
        .passed   (pass_a),
        .failed   (fail_a),
        .cov_miss (miss_a)
    );

    sync_fifo_tb_sb #(.DEPTH(DB), .WIDTH(WB)) sb_b (
        .clk      (clk),
        .rst_n    (rst_n),
        .wr_en    (wr_en),
        .wr_data  (wr_data),
        .rd_en    (rd_en),
        .full     (full_b),
        .empty    (empty_b),
        .count    (count_b),
        .rd_data  (rd_data_b),
        .passed   (pass_b),
        .failed   (fail_b),
        .cov_miss (miss_b)
    );

    // Drive one cycle of inputs at the falling edge (sampled at the next rising edge)
    task drive(input rst, input w, input r);
        reg [31:0] rnd;
        begin
            @(negedge clk);
            rnd     = $random;
            rst_n   = rst;
            wr_en   = w;
            rd_en   = r;
            wr_data = rnd[WB-1:0];
        end
    endtask

    // Random traffic with given write / read request percentages
    task rand_phase(input integer n, input integer wpct, input integer rpct);
        integer    j;
        reg [31:0] r1;
        reg [31:0] r2;
        begin
            for (j = 0; j < n; j = j + 1) begin
                r1 = $random;
                r2 = $random;
                drive(1'b1, ((r1 % 32'd100) < wpct), ((r2 % 32'd100) < rpct));
            end
        end
    endtask

    // Coverage goals (bit order matches sync_fifo_tb_sb cov_miss)
    task report_cov(input [9:0] miss, input integer depth);
        begin
            if (miss[0]) begin failed = failed + 32'd1; $error("DEPTH %0d: coverage not reached: filled to full", depth); end
            else passed = passed + 32'd1;
            if (miss[1]) begin failed = failed + 32'd1; $error("DEPTH %0d: coverage not reached: write while full", depth); end
            else passed = passed + 32'd1;
            if (miss[2]) begin failed = failed + 32'd1; $error("DEPTH %0d: coverage not reached: drained from full to empty", depth); end
            else passed = passed + 32'd1;
            if (miss[3]) begin failed = failed + 32'd1; $error("DEPTH %0d: coverage not reached: read while empty", depth); end
            else passed = passed + 32'd1;
            if (miss[4]) begin failed = failed + 32'd1; $error("DEPTH %0d: coverage not reached: write and read together when empty", depth); end
            else passed = passed + 32'd1;
            if (miss[5]) begin failed = failed + 32'd1; $error("DEPTH %0d: coverage not reached: write and read together when full", depth); end
            else passed = passed + 32'd1;
            if (miss[6]) begin failed = failed + 32'd1; $error("DEPTH %0d: coverage not reached: write and read together in between", depth); end
            else passed = passed + 32'd1;
            if (miss[7]) begin failed = failed + 32'd1; $error("DEPTH %0d: coverage not reached: write pointer wrap-around", depth); end
            else passed = passed + 32'd1;
            if (miss[8]) begin failed = failed + 32'd1; $error("DEPTH %0d: coverage not reached: read pointer wrap-around", depth); end
            else passed = passed + 32'd1;
            if (miss[9]) begin failed = failed + 32'd1; $error("DEPTH %0d: coverage not reached: reset during traffic", depth); end
            else passed = passed + 32'd1;
        end
    endtask

    initial begin
        rst_n   = 1'b0;
        wr_en   = 1'b0;
        rd_en   = 1'b0;
        wr_data = {WB{1'b0}};
        passed  = 32'd0;
        failed  = 32'd0;
        nonce   = {(8*64){1'b0}};

        // Reset
        repeat (3) drive(1'b0, 1'b0, 1'b0);
        drive(1'b1, 1'b0, 1'b0);

        // Fill to full, then writes while full
        repeat (10) drive(1'b1, 1'b1, 1'b0);
        // Write and read together when full, then in between
        repeat (2) drive(1'b1, 1'b1, 1'b1);
        // Drain to empty, then reads while empty
        repeat (14) drive(1'b1, 1'b0, 1'b1);
        // Write and read together when empty
        drive(1'b1, 1'b1, 1'b1);
        // Steady write and read in between
        repeat (4) drive(1'b1, 1'b1, 1'b1);

        // Random traffic, biased to reach full and empty repeatedly
        rand_phase(300, 70, 30);
        rand_phase(300, 30, 70);
        rand_phase(300, 50, 50);

        // Reset during traffic (requests during reset must be ignored)
        repeat (3) drive(1'b1, 1'b1, 1'b0);
        repeat (2) drive(1'b0, 1'b1, 1'b1);
        drive(1'b1, 1'b0, 1'b0);

        rand_phase(200, 60, 40);

        // Final drain
        repeat (20) drive(1'b1, 1'b0, 1'b1);
        drive(1'b1, 1'b0, 1'b0);
        @(negedge clk);
        #1;

        passed = pass_a + pass_b;
        failed = fail_a + fail_b;
        report_cov(miss_a, DA);
        report_cov(miss_b, DB);

        if ($value$plusargs("nirmaan_nonce=%s", nonce) == 0) begin
            nonce = {(8*64){1'b0}};
        end
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

