// sync_fifo_tb_sb.v
// Reference-queue scoreboard for one sync_fifo instance.
// Model update on the rising edge from the sampled inputs; checks of
// full, empty, count and rd_data on every falling edge.
// The queue is indexed by 8-bit push/pop sequence numbers (DEPTH < 256).
`default_nettype none

module sync_fifo_tb_sb #(
    parameter integer DEPTH = 8,
    parameter integer WIDTH = 8
) (
    input  wire                       clk,
    input  wire                       rst_n,
    input  wire                       wr_en,
    input  wire [WIDTH-1:0]           wr_data,
    input  wire                       rd_en,
    input  wire                       full,
    input  wire                       empty,
    input  wire [$clog2(DEPTH+1)-1:0] count,
    input  wire [WIDTH-1:0]           rd_data,
    output wire [31:0]                passed,
    output wire [31:0]                failed,
    output wire [9:0]                 cov_miss
);

    localparam integer CW      = $clog2(DEPTH + 1);
    localparam [31:0]  DEPTH32 = DEPTH;
    localparam [31:0]  LAST32  = DEPTH - 1;

    reg             started;
    reg [7:0]       push_no;
    reg [7:0]       pop_no;
    reg [WIDTH-1:0] hist [0:255];
    reg [31:0]      pushes;
    reg [31:0]      pops;
    reg             was_full;

    reg [31:0] n_pass;
    reg [31:0] n_fail;

    reg [31:0] cov_full;
    reg [31:0] cov_wr_full;
    reg [31:0] cov_full_empty;
    reg [31:0] cov_rd_empty;
    reg [31:0] cov_both_empty;
    reg [31:0] cov_both_full;
    reg [31:0] cov_both_mid;
    reg [31:0] cov_wr_wrap;
    reg [31:0] cov_rd_wrap;
    reg [31:0] cov_rst;

    wire [7:0]       m_cnt     = push_no - pop_no;
    wire [31:0]      m_cnt32   = {24'd0, m_cnt};
    wire [31:0]      dut_cnt32 = {{(32-CW){1'b0}}, count};
    wire             m_full    = (m_cnt32 == DEPTH32);
    wire             m_empty   = (m_cnt32 == 32'd0);
    wire             m_wr      = wr_en && !m_full;
    wire             m_rd      = rd_en && !m_empty;
    wire [WIDTH-1:0] m_head    = hist[pop_no];

    initial begin
        started        = 1'b0;
        push_no        = 8'd0;
        pop_no         = 8'd0;
        pushes         = 32'd0;
        pops           = 32'd0;
        was_full       = 1'b0;
        n_pass         = 32'd0;
        n_fail         = 32'd0;
        cov_full       = 32'd0;
        cov_wr_full    = 32'd0;
        cov_full_empty = 32'd0;
        cov_rd_empty   = 32'd0;
        cov_both_empty = 32'd0;
        cov_both_full  = 32'd0;
        cov_both_mid   = 32'd0;
        cov_wr_wrap    = 32'd0;
        cov_rd_wrap    = 32'd0;
        cov_rst        = 32'd0;
    end

    // Reference model and coverage, from the state before the edge
    always @(posedge clk) begin
        if (!rst_n) begin
            if (started && !m_empty) cov_rst <= cov_rst + 32'd1;
            started  <= 1'b1;
            push_no  <= 8'd0;
            pop_no   <= 8'd0;
            pushes   <= 32'd0;
            pops     <= 32'd0;
            was_full <= 1'b0;
        end else if (started) begin
            if (m_wr) begin
                hist[push_no] <= wr_data;
                push_no       <= push_no + 8'd1;
                pushes        <= pushes + 32'd1;
                if ((pushes % DEPTH32) == LAST32) cov_wr_wrap <= cov_wr_wrap + 32'd1;
            end
            if (m_rd) begin
                pop_no <= pop_no + 8'd1;
                pops   <= pops + 32'd1;
                if ((pops % DEPTH32) == LAST32) cov_rd_wrap <= cov_rd_wrap + 32'd1;
            end
            if (wr_en && m_full)                       cov_wr_full    <= cov_wr_full + 32'd1;
            if (rd_en && m_empty)                      cov_rd_empty   <= cov_rd_empty + 32'd1;
            if (wr_en && rd_en && m_empty)             cov_both_empty <= cov_both_empty + 32'd1;
            if (wr_en && rd_en && m_full)              cov_both_full  <= cov_both_full + 32'd1;
            if (wr_en && rd_en && !m_empty && !m_full) cov_both_mid   <= cov_both_mid + 32'd1;
            if (m_full) begin
                cov_full <= cov_full + 32'd1;
                was_full <= 1'b1;
            end
            if (m_empty && was_full) begin
                cov_full_empty <= cov_full_empty + 32'd1;
                was_full       <= 1'b0;
            end
        end
    end

    // Output checks, every cycle
    always @(negedge clk) begin
        if (started) begin
            if (full === m_full) n_pass = n_pass + 32'd1;
            else begin
                n_fail = n_fail + 32'd1;
                $error("sync_fifo DEPTH %0d WIDTH %0d: full is %b, expected %b (model count %0d)",
                       DEPTH, WIDTH, full, m_full, m_cnt);
            end

            if (empty === m_empty) n_pass = n_pass + 32'd1;
            else begin
                n_fail = n_fail + 32'd1;
                $error("sync_fifo DEPTH %0d WIDTH %0d: empty is %b, expected %b (model count %0d)",
                       DEPTH, WIDTH, empty, m_empty, m_cnt);
            end

            if (dut_cnt32 === m_cnt32) n_pass = n_pass + 32'd1;
            else begin
                n_fail = n_fail + 32'd1;
                $error("sync_fifo DEPTH %0d WIDTH %0d: count is %0d, expected %0d",
                       DEPTH, WIDTH, count, m_cnt);
            end

            if (!(full && empty)) n_pass = n_pass + 32'd1;
            else begin
                n_fail = n_fail + 32'd1;
                $error("sync_fifo DEPTH %0d WIDTH %0d: full and empty both high", DEPTH, WIDTH);
            end

            if (!m_empty) begin
                if (rd_data === m_head) n_pass = n_pass + 32'd1;
                else begin
                    n_fail = n_fail + 32'd1;
                    $error("sync_fifo DEPTH %0d WIDTH %0d: rd_data is %h, expected %h",
                           DEPTH, WIDTH, rd_data, m_head);
                end
            end
        end
    end

    assign passed = n_pass;
    assign failed = n_fail;

    assign cov_miss[0] = (cov_full       == 32'd0);
    assign cov_miss[1] = (cov_wr_full    == 32'd0);
    assign cov_miss[2] = (cov_full_empty == 32'd0);
    assign cov_miss[3] = (cov_rd_empty   == 32'd0);
    assign cov_miss[4] = (cov_both_empty == 32'd0);
    assign cov_miss[5] = (cov_both_full  == 32'd0);
    assign cov_miss[6] = (cov_both_mid   == 32'd0);
    assign cov_miss[7] = (cov_wr_wrap    == 32'd0);
    assign cov_miss[8] = (cov_rd_wrap    == 32'd0);
    assign cov_miss[9] = (cov_rst        == 32'd0);

endmodule

